(() => {
  const $ = (sel) => document.querySelector(sel);
  const inp = $('#inp');
  const btn = $('#btn');
  const btnRand = $('#btnRand');
  const strip = $('#strip');
  const mono = $('#mono');
  const noticed = $('#noticed');
  const suggest = $('#suggest');
  const forced = $('#forced');
  const nn = $('#nn');
  const nnWhy = $('#nnWhy');

  const examples = [
    'Καρνος', 'Αορνος', 'Πυρνος', 'Σαμορνος', 'Φαλερνος', 'πατερνος', 'Ιουερνος', 'Αροερνος',
    'Λιβυρνος', 'Αχαρνος', 'Γοννοι', 'Σιγυννος', 'Τυρρηνος', 'Τυρρανος'
  ];

  // --- Greek helpers (toy-level) ---
  const combining = {
    acute: '\u0301',
    grave: '\u0300',
    circumflex: '\u0342',
    diaeresis: '\u0308'
  };

  const precomposedAcute = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };

  const tonosToOxia = (s) => s.replace(/\u0384/g, '\u0301');

  function stripDiacritics(s){
    // Remove most combining marks used in Greek polytonic/monotonic.
    return s.normalize('NFD').replace(/[\u0300-\u036f\u1fbd\u1fbf\u1ffe\u0384\u00b4]/g,'').normalize('NFC');
  }

  function toMonotonic(s){
    // Keep only acute/tonos; remove other marks.
    let n = s.normalize('NFD');
    // Convert grave/circumflex to acute for simplicity.
    n = n.replace(/\u0300|\u0342/g, combining.acute);
    // Remove breathings, iota subscript, etc.
    n = n.replace(/[\u0313\u0314\u0345\u0306\u0304\u0308\u0323\u0343\u0344]/g,'');
    // Collapse multiple acutes on same base (rare)
    n = n.replace(/\u0301\u0301+/g, combining.acute);
    return n.normalize('NFC');
  }

  function isGreekVowel(ch){
    return /[αεηιουωΑΕΗΙΟΥΩ]/.test(ch);
  }

  function vowelIndices(word){
    const w = word.normalize('NFD');
    const base = [];
    // Map indices in NFC string is hard; we operate on NFD array and later rebuild.
    // We'll return indices of vowel base letters in the NFD array.
    const arr = Array.from(w);
    for(let i=0;i<arr.length;i++){
      const c = arr[i];
      if(isGreekVowel(c)) base.push(i);
    }
    return {arr, base};
  }

  function applyAcuteOnVowel(word, vowelFromEnd){
    // vowelFromEnd: 1=last vowel, 2=penult vowel, 3=antepenult vowel
    let w = word;
    if(strip.checked) w = stripDiacritics(w);

    const {arr, base} = vowelIndices(w);
    if(base.length === 0) return w;
    const target = base[base.length - vowelFromEnd];
    if(target == null) return w;

    // Insert combining acute after the vowel base letter, unless it already has one.
    // Remove existing accent marks if strip is on (already done).
    // If monotonic output requested, we can use precomposed tonos for simple vowels.
    arr[target] = arr[target];

    // If next char(s) are combining marks, we still just add acute right after base.
    arr.splice(target+1, 0, combining.acute);
    let out = arr.join('').normalize('NFC');

    if(mono.checked) out = toMonotonic(out);
    return out;
  }

  function endsWithNosLike(s){
    const t = stripDiacritics(s).trim();
    return /νος\b/i.test(t) || /nos\b/i.test(t); // allow latin 'nos' just in case
  }

  function classify(word){
    const raw = word.trim();
    const w = stripDiacritics(raw);
    const wLower = w.toLowerCase();

    const info = {
      raw,
      stripped: w,
      hasNos: /νος$/.test(wLower),
      hasRnos: /ρνος$/.test(wLower),
      hasErnos: /ερνος$/.test(wLower),
      hasYrnósException: /λιβυρνος$/.test(wLower),
      hasDoubleN: /νν/.test(wLower),
      endsNoi: /νοι$/.test(wLower)
    };

    // Suggestion logic (toy):
    // -ερνος => penult
    // ρνος => barytone => choose penult if possible, else antepenult
    // exception: Λιβυρνός oxytone (as passage says)
    let suggestion = null;
    let reason = [];

    if(info.hasErnos){
      suggestion = {pos:'pen', vowelsFromEnd:2};
      reason.push('Looks like …ερνος → paroxytone (penult) per passage.');
    }

    if(info.hasRnos){
      if(info.hasYrnósException){
        suggestion = {pos:'ult', vowelsFromEnd:1};
        reason.push('Matches Λιβυρνος → passage says oxytone (Λιβυρνός).');
      } else {
        // barytone: avoid last; prefer penult if exists
        suggestion = {pos:'pen', vowelsFromEnd:2};
        reason.push('Looks like …ρνος → barytone (avoid final accent) per passage; toy chooses penult.');
      }
    }

    if(!suggestion && info.hasNos){
      reason.push('Ends in -νος, but no specific trigger (…ρνος / …ερνος) found.');
      suggestion = {pos:null, vowelsFromEnd:null};
    }

    if(!info.hasNos){
      reason.push('Does not end in -νος (toy rules may not apply).');
      suggestion = {pos:null, vowelsFromEnd:null};
    }

    return {info, reason, suggestion};
  }

  function nnSuggestion(word){
    const raw = word.trim();
    const w = stripDiacritics(raw);
    const wl = w.toLowerCase();

    // Very naive: if ends -νοι and has single ν before it after a vowel, suggest doubling.
    // e.g. Γοννοι from Γονοι.
    let out = null;
    let why = '';

    if(/νοι$/.test(wl)){
      // Find the ν that begins the ending
      const idx = wl.lastIndexOf('νοι');
      const before = wl.slice(0, idx);
      const lastChar = before.slice(-1);
      const lastTwo = before.slice(-2);

      const already = /νν/.test(wl.slice(idx-1, idx+3));
      if(already){
        out = raw;
        why = 'Already contains νν near the -νοι ending.';
      } else if(lastChar && /[αεηιουω]/.test(lastChar)){
        // Insert extra ν
        const suggested = w.slice(0, idx) + 'ν' + w.slice(idx);
        out = mono.checked ? toMonotonic(suggested) : suggested;
        why = 'Ends in -νοι after a vowel; toy suggests νν (cf. Γόννοι in the passage).';
      } else if(lastTwo.endsWith('ν')){
        out = raw;
        why = 'Already has ν right before -νοι; toy leaves it alone.';
      } else {
        out = raw;
        why = 'No obvious place to suggest νν.';
      }
    } else {
      out = raw;
      why = 'Type something ending in -νοι (e.g. Γοννοι) to see the νν spotter.';
    }

    return {out, why};
  }

  function render(){
    const text = inp.value.trim();
    if(!text){
      noticed.textContent = '—';
      suggest.textContent = '—';
      forced.textContent = '—';
      nn.textContent = '—';
      nnWhy.textContent = '';
      return;
    }

    const {info, reason, suggestion} = classify(text);

    const lines = [];
    lines.push(`Input: ${info.raw}`);
    lines.push(`Stripped: ${info.stripped}`);
    lines.push(`Ends -νος: ${info.hasNos ? 'yes' : 'no'}`);
    lines.push(`…ρνος: ${info.hasRnos ? 'yes' : 'no'}`);
    lines.push(`…ερνος: ${info.hasErnos ? 'yes' : 'no'}`);
    if(info.hasYrnósException) lines.push('Special case: Λιβυρνος');
    lines.push('');
    lines.push('Notes:');
    reason.forEach(r => lines.push('• ' + r));
    noticed.textContent = lines.join('\n');

    let sugForm = text;
    if(suggestion && suggestion.vowelsFromEnd){
      sugForm = applyAcuteOnVowel(text, suggestion.vowelsFromEnd);
    } else {
      sugForm = mono.checked ? toMonotonic(text) : text;
      if(strip.checked) sugForm = stripDiacritics(sugForm);
    }
    suggest.textContent = sugForm;

    // default forced = suggested
    forced.textContent = sugForm;

    const nnRes = nnSuggestion(text);
    nn.textContent = nnRes.out;
    nnWhy.textContent = nnRes.why;
  }

  // Force buttons
  document.addEventListener('click', (e) => {
    const b = e.target.closest('button[data-force]');
    if(!b) return;
    const text = inp.value.trim();
    if(!text) return;
    const mode = b.getAttribute('data-force');
    const map = {ult:1, pen:2, ant:3};
    const v = map[mode];
    forced.textContent = applyAcuteOnVowel(text, v);
  });

  btn.addEventListener('click', render);
  inp.addEventListener('keydown', (e) => { if(e.key === 'Enter') render(); });
  strip.addEventListener('change', render);
  mono.addEventListener('change', render);

  btnRand.addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inp.value = ex;
    render();
  });

  // initial
  inp.value = 'Καρνος';
  render();
})();

